sql.where:
sp.deleted = 0

  AND sp.department_id = #{departmentId}


  AND sp.period_year = #{year}


  AND sp.period_month = #{month}

mapper.select:
SELECT id, department_id, period_year, period_month, manhours, accident_count,
       lost_time_count, fatality_count, trir, ltir, budget_planned, budget_used,
       fcm_project_code, vbp_project_code, reported_by, comment,
       created_at, updated_at, deleted
  FROM tb_safety_performance_land
 WHERE department_id = #{departmentId}
   AND period_year = #{periodYear}
   AND period_month = #{periodMonth}
   AND deleted = 0
